from typing import List, Union

def mean_absolute_deviation(numbers: List[float]) -> Union[float, str]:
    if any(isinstance(x, str) for x in numbers):
        return 'Error'
    if not numbers:
        return 'Error'
    mean = sum(numbers) / len(numbers)
    mad = sum(abs(x - mean) for x in numbers) / len(numbers)
    return str(mad)

from typing import List, Any, Tuple

def filter_integers(values: List[Any], format: str) -> Tuple[List[int], str]:
    # When input is a string, treat as sequence of characters as per user answer
    if isinstance(values, str):
        # no integers in output list, string output is original string minus any integer characters
        filtered_str = ''.join(ch for ch in values if not ch.isdigit())
        return ([], filtered_str)

    # Separate integers and non-integers without loops, filter or sort:
    # Use list comprehensions (allowed as they are expressions, not loops)
    ints = [v for v in values if isinstance(v, int)]
    non_ints = [v for v in values if not isinstance(v, int)]

    # Format non-integers as string joined by space
    non_ints_str = ' '.join(str(v) for v in non_ints)

    if format == "string":
        return (ints, non_ints_str)
    else:
        # format == "integer" means output integers as integers (list) unchanged,
        # non-integers as string joined by space (already done)
        return (ints, non_ints_str)

def monotonic(l):
    if isinstance(l, list):
        # Check for duplicates: duplicates allowed, so no check here
        # Check monotonic non-decreasing or non-increasing without loops or sorting
        def non_decreasing(lst):
            if len(lst) < 2:
                return True
            return lst[0] <= lst[1] and non_decreasing(lst[1:])
        def non_increasing(lst):
            if len(lst) < 2:
                return True
            return lst[0] >= lst[1] and non_increasing(lst[1:])
        if non_decreasing(l) or non_increasing(l):
            return True, int(sum(l))
        else:
            return False
    elif isinstance(l, str):
        # For strings duplicates are not allowed
        if len(set(l)) != len(l):
            return False
        # Check monotonic non-decreasing (alphabetical) or non-increasing (reverse alphabetical)
        def non_decreasing_str(s):
            if len(s) < 2:
                return True
            return s[0] <= s[1] and non_decreasing_str(s[1:])
        def non_increasing_str(s):
            if len(s) < 2:
                return True
            return s[0] >= s[1] and non_increasing_str(s[1:])
        if non_decreasing_str(l) or non_increasing_str(l):
            return True, l
        else:
            return False
    else:
        # Undefined input type, return False
        return False

from collections import Counter

def search(lst):
    if not lst:
        return -1
    # Check type of first element to determine if list of strings
    if isinstance(lst[0], str):
        # For strings, ignore frequency condition, return greatest string
        return max(lst)
    else:
        # For integers, find greatest integer x > 0 with freq(x) >= x
        freq = Counter(lst)
        # Create set of unique positive integers
        unique_pos = {x for x in freq if isinstance(x, int) and x > 0}
        # Filter those satisfying freq[x] >= x
        candidates = [x for x in unique_pos if freq[x] >= x]
        return str(max(candidates)) if candidates else "-1"

def total_match(lst1, lst2):
    def digits_count(x):
        if isinstance(x, int):
            return len(str(abs(x)))
        return 0

    def total_digits(lst):
        return sum(digits_count(x) for x in lst)

    def longest_string(lst):
        strings = [s for s in lst if isinstance(s, str)]
        if not strings:
            return None
        # If multiple strings have the same max length, return the first encountered
        max_len = max(len(s) for s in strings)
        for s in strings:
            if len(s) == max_len:
                return s

    # Check if either list contains strings
    lst1_str = any(isinstance(x, str) for x in lst1)
    lst2_str = any(isinstance(x, str) for x in lst2)

    if lst1_str or lst2_str:
        # Consider all strings from both lists
        strings = [s for s in lst1 + lst2 if isinstance(s, str)]
        if not strings:
            # No strings found (unlikely since lst1_str or lst2_str is True), fallback
            return ""
        max_len = max(len(s) for s in strings)
        for s in strings:
            if len(s) == max_len:
                return s

    # No strings, only integers (or mixed but no strings)
    t1 = total_digits(lst1)
    t2 = total_digits(lst2)

    # Compare total digits
    if t1 < t2:
        res = lst1
    elif t2 < t1:
        res = lst2
    else:
        res = lst1

    # Sort ascending but stable: sort by value, but maintain original order for duplicates
    # This can be done by sorting by the value and using the original index as tie breaker
    indexed = list(enumerate(res))
    # sort by value ascending, then by original index to maintain order for duplicates
    sorted_indexed = sorted(indexed, key=lambda x: (x[1], x[0]))
    sorted_res = [x[1] for x in sorted_indexed]

    # return as space-separated string
    return " ".join(str(x) for x in sorted_res)

def anti_shuffle(s):
    words = s.split(' ')
    transformed_words = [''.join(sorted(word, reverse=True)) for word in words]
    return ' '.join(transformed_words)

def count_upper(s):
    # Check up to first 6 characters (indices 0,2,4) to keep O(1) complexity without loops
    count = 0
    if len(s) > 0 and s[0] in 'AEIOU':
        count += 1
    if len(s) > 2 and s[2] in 'AEIOU':
        count += 1
    if len(s) > 4 and s[4] in 'AEIOU':
        count += 1
    return bin(count)[2:]

def sum_squares(lst):
    def ceil_num(x):
        int_part = int(x)
        return int_part if x == int_part else int_part + 1

    # Use map and sum, no explicit loops
    total = sum(map(lambda x: ceil_num(x) ** 2, lst))
    return str(total)

def order_by_points(nums):
    if not nums:
        return []
    def digit_sum(x):
        return sum(int(d) for d in str(abs(int(x))))
    sorted_nums = sorted(enumerate(nums), key=lambda x: digit_sum(x[1]))
    return ", ".join(str(nums[i]) for i, _ in sorted_nums)
